function commandResults(q){const routes=[...navItems,['settings','gear','Configurações'],['home','external','Site do Keep']].filter(n=>n[2].toLowerCase().includes(q.toLowerCase()));return routes.length?routes.map(n=>'<a class="command-result" href="'+(n[0]==='home'?'/':'/app/'+n[0])+'">'+icon(n[1],17)+n[2]+icon('arrow',13)+'</a>').join(''):empty('Nada com esse nome.','Tente “artigos”, “radar” ou “editor”.');}
function compareModal(){modal('Duas marcas. Um olhar mais claro.','<div class="compare-grid"><div class="head">O que observar</div><div class="head">Adfert</div><div class="head">Intrivia</div>'+[['Artigos em português','40','18'],['Total de URLs','114','18'],['Links para soluções','10 de 40','4 de 18'],['Sem ligação comercial','30 artigos','14 artigos'],['Idiomas','PT · EN · ES','PT-BR'],['Primeira resposta','168 ms','269 ms']].map(r=>r.map(v=>'<div>'+v+'</div>').join('')).join('')+'</div><p class="fine-print">Números históricos do handoff. Não representam uma coleta ao vivo.</p>',btn('Voltar ao painel','close-modal','',''),true);}
function go(path){
 if(location.pathname===path){route();return;}
 history.pushState(null,'',path);
 route();
}
function route(){
 const path=(location.pathname.replace(/\/+$/,'')||'/');
 const hash=location.hash;
 if(path==='/' && hash.startsWith('#') && hash.length>1 && !hash.startsWith('#/')){
  if(currentRoute!=='home'){currentRoute='home';$('#root').innerHTML=landing();}
  requestAnimationFrame(()=>document.getElementById(hash.slice(1))?.scrollIntoView({behavior:'smooth'}));return;
 }
 closeModal();state.mobileMenu=false;state.appSidebar=false;
 const parts=path==='/'?[]:path.slice(1).split('/');const first=parts[0]||'';
 const session=window.KeepAuth&&window.KeepAuth.session;
 if(first==='login'&&session&&session.user.email_confirmed_at){go('/app/overview');return;}
 if(first==='app'){
  if(!session||!session.user.email_confirmed_at){
   state.authNotice=session?'Confirme o e-mail para abrir o painel.':'';
   if(path!=='/login')go('/login');
   else{$('#root').innerHTML=authPage(false);}
   return;
  }
  state.profile=session.user.email||state.profile;
  const page=parts[1]||'overview';const screens={overview,radar,prompts:promptPage,audit:auditPage,articles:articlesPage,writer:writerPage,editor:editorPage,media:mediaPage,integrations:integrationsPage,plan:planPage,settings:settingsPage};
  currentRoute='app/'+page;document.title='Keep — '+(navItems.find(n=>n[0]===page)?.[2]||(page==='writer'?'Editor de artigo':'Configurações'));
  $('#root').innerHTML=appShell(page,(screens[page]||overview)());
 }else if(first==='login'||first==='onboarding'){currentRoute=first;document.title='Keep — Seu próximo passo';$('#root').innerHTML=authPage(first==='onboarding');}
 else{currentRoute='home';document.title='Keep — Publicar ficou fácil. Virar referência é outra história.';$('#root').innerHTML=landing();}
 if(currentRoute==='app/editor'&&state.page.imageId){const chosen=baseMedia.concat(state.media).find(m=>m.id===state.page.imageId);const gallery=$('#cms-gallery');if(chosen&&gallery)gallery.firstElementChild.innerHTML=chosen.src?'<img src="'+chosen.src+'" alt="'+esc(chosen.name)+'" style="width:100%;height:100%;object-fit:contain;background:'+chosen.color+'">':icon(chosen.icon,35);}
 updateResponsiveNavigation();
 window.scrollTo({top:0,behavior:'instant'});
}
function updateResponsiveNavigation(){const side=$('.sidebar');if(side)side.inert=window.innerWidth<=760&&!state.appSidebar;}
window.addEventListener('resize',updateResponsiveNavigation);
function rerender(){const y=window.scrollY;route();window.scrollTo({top:y,behavior:'instant'});}
function refreshResults(id,fn){const el=$(id);if(el)el.innerHTML=fn();}
